    original=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if original[r][c] in (1,2,3,4,6):
                mc=mirror_sum-c
                if 0<=mc<w and g[r][mc]==0:
                    g[r][mc]=original[r][c]
    return g
'''
